tability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"","type":"address"},{"internalType":"bytes4","name":"","type":"bytes4"}],"name":"voucherTerms","outputs":[{"internalType":"uint64","name":"rewardsGranted","type":"uint64"},{"internalType":"uint64","name":"limit","type":"uint64"},{"internalType":"uint64","name":"amount","type":"uint64"},{"internalType":"bool","name":"enabled","type":"bool"},{"internalType":"uint56","name":"_reserved","type":"uint56"}],"stateMutability":"view","type":"function"}],"devdoc":{"kind":"dev","methods":{"accountRewards(uint256[],((uint256,uint256),(uint256[2],uint256[2]),(uint256,uint256)),uint32,uint96,bytes)":{"details":"Validates and processes UTXO rewards accounting. The user chooses whether UTXOs are added quickly via the taxi tree or slowly via the bus tree using `transactionOptions`. Also handles validation of public inputs and spends the nullifier of the UTXO being used. Emits `RewardClaimed` upon successful claim and processes associated rewards.","params":{"inputs":"The public input parameters to be passed to the verifier (see `PrpAccountingPublicSignals.sol`).","paymasterCompensation":"Compensation for the paymaster.","privateMessages":"Private message of the user. (see `TransactionNoteEmitter.sol`).","proof":"The zero knowledge proof","transactionOptions":"A 17-bit number where the 8 LSB defines the cachedForestRootIndex, the 1 MSB enables/disables the taxi tree, and other bits are reserved."},"returns":{"utxoBusQueuePos":"The position in the UTXO bus queue for the first UTXO."}},"generateRewards(bytes32,uint64,bytes4)":{"details":"Verifies if the voucher type is valid, then creates a reward voucher for the secret hash with the specified amount. Emits the `RewardVoucherGenerated` event upon successful creation.","params":{"_amount":"The amount of the reward voucher.","_secretHash":"The secret hash for the reward voucher.","_voucherType":"The type of the reward voucher."},"returns":{"_prpToGrant