ntracts/protocol/v1/core/facets/PrpVoucherController.sol":"PrpVoucherController"},"evmVersion":"paris","libraries":{},"metadata":{"bytecodeHash":"none","useLiteralContent":true},"optimizer":{"enabled":true,"runs":800},"remappings":[]},"sources":{"contracts/common/Bytecode.sol":{"content":"// SPDX-License-Identifier: AGPL-3.0-only
