pragma solidity ^0.8.19;

import "./../../../../common/UtilsLib.sol";

library TokenTypeAndAddressDecoder {
    using UtilsLib for uint256;

    function getTokenTypeAndAddress(
        uint256 tokenTypeAndAddress
    ) internal pure returns (uint8 tokenType, address tokenAddress) {
        // 8 MSB
        tokenType = (tokenTypeAndAddress >> 160).safe8();

        // 160 LSB
        tokenAddress = (tokenTypeAndAddress & type(uint160).max).safeAddress();
    }
}
","keccak256":"0x4eeddc674de8ed8418c7008ec297163cf0141e4a120471bba4033efdf4709a20","license":"GPL-3.0-only"},"contracts/protocol/v1/core/libraries/TransactionOptions.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
// SPDX-FileCopyrightText: Copyright 2021-25 Panther Protocol Foundation
pragma solidity ^0.8.19;

library TransactionOptions {
    function cachedForestRootIndex(
        uint32 transactionOptions
    ) internal pure returns (uint256) {
        // The 8 LSB contains the cachedForestRootIndex
        // returning the total 16 bits to reduce attack surface.

        return transactionOptions & 0xFFFF;
    }

    function isTaxiApplicable(
        uint32 transactionOptions
    ) internal pure returns (bool) {
        // The 1 MSB contains the TaxiEnabler

        return (transactionOptions >> 16) & 1 == 1;
    }
}
